var main = tree.current_scene
var H = load("res://tests/helpers/cus11e_c5_scen.gd")
var ph = H.phase()
for e in ph.get_unfought_eligible_units():
	ph.sequencer_11e.mark_fought(str(e.get("unit_id", "")), GameState.state)
for _i in range(4):
	if int(ph.consolidation_step_11e) == int(ph.ConsolidationStep11e.ACTIVE):
		break
	ph.execute_action({"type": "END_FIGHT", "player": int(GameState.get_active_player())})
return int(ph.consolidation_step_11e) == int(ph.ConsolidationStep11e.ACTIVE)

